@startuml

class Home {
  + Name : string
}

class Department {
  + Name : string
}

class Room {
  + RoomNumber : string
}

class Bed {
  + BedNumber : string
}

class Category {
  + Name : string
  + Price : double
}

enum StayType {
  RH
  RNH
  SF
}

class Inhabitant {
  + Name : string
  + IdentificationData : string
  + RegistrationDate : date
}

class Assessment {
  + NeedsScore : int
  + RecommendedStayType : StayType
}

class WaitingList {
  + Position : int
}

class Stay {
  + Status : string
  + IntakeDate : date
  + Discount : double
}

class Proposal {
  + ProposalDate : date
  + Status : string
}

class Invoice {
  + InvoiceNumber : string
  + OutstandingAmount : double
  + Status : string
}

class CreditNote {
  + Amount : double
}

class PaymentEvent {
  + Amount : double
  + PaymentDate : date
}

Home "1" *-- "1..*" Department
Department "1" *-- "1..*" Room
Room "1" *-- "1..*" Bed
Bed "1" -- "1" Category
Inhabitant "1" -- "1..*" Stay
Stay "1" -- "1" Category
Stay "1" -- "0..*" Invoice
Inhabitant "1" -- "0..*" Assessment
Inhabitant "1" -- "0..*" Proposal
Stay "1" -- "0..*" Proposal
WaitingList "1" -- "1..*" Inhabitant
Invoice "1" -- "0..*" PaymentEvent
Invoice "1" -- "0..1" CreditNote

@enduml

